// Exam 2 Course Reading Questions (docs/exam2/02-course-reading-questions.md) as one-way recall cards.
// The review lecture: “Most test questions are based on these.” Answers from Powell (9th ed.) and the lecture slides.
(function () {
  "use strict";
  const SETS = {
    w6t: ["e2c1", "Sept 29 · Powell 10"], w6r: ["e2c3", "Oct 1 · Powell 11"], w7t: ["e2c4", "Oct 6 · Powell 12"], w7r: ["e2c5", "Oct 8 · Powell 13"],
    w8t: ["e2c6", "Oct 13 · Powell 14"], w8r: ["e2c7", "Oct 15 · Powell 18"], w9t: ["e2c8", "Oct 20 · Powell 16"], w9r: ["e2c9", "Oct 22 · Powell 17"]
  };
  const cards = [];
  const C = (set, items) => items.forEach(([q, a, cluster], i) => cards.push({
    id: `crq-${set}-${String(i + 1).padStart(2, "0")}`, term: q, cat: "crq", cluster: cluster || SETS[set][0], guide: a, more: [],
    oneWay: true, cardLabel: `Reading question · ${SETS[set][1]}`
  }));

  C("w6t", [
    ["Find Eleusis on a map. What important sanctuary was located at Eleusis?", "Eleusis lies about 14 miles west of Athens (in Attica). Site of the sanctuary of Demeter (and Persephone) — home of the Eleusinian Mysteries.", "e2c1"],
    ["What specific kinds of fertility do Artemis, Aphrodite and Hera govern?", "Artemis: the fertility of wild animals (and childbirth). Aphrodite: human sexuality. Hera: marriage and the family."],
    ["Who is Demeter’s daughter? What is another name for her?", "Persephone, also called Korê (“daughter/girl”); Roman Proserpina."],
    ["What is a wrath (menis) story? Give one example from this chapter. Give one example from a previous chapter.", "Offense against a god → the god's anger → widespread destruction → appeasement with a new ritual/honors. This chapter: Demeter's wrath over Persephone (also Demeter at Eleusis). Earlier: Apollo's plague in Iliad 1 (or Zeus' flood after Lycaon)."],
    ["What causes Demeter’s anger, in the Homeric Hymn to Demeter? What does she do to humans out of grief for her daughter?", "Hades abducts Persephone with Zeus' consent (Helios tells her). She leaves Olympus, and after Eleusis she stops the grain from growing — a famine that threatens to destroy humankind and the gods' offerings."],
    ["What does Zeus instruct Hermes to do? What prevents him from fulfilling his mission?", "Go down to Hades and bring Persephone back to her mother. Hades secretly gives her a pomegranate seed to eat, so she must return below for part of every year."],
    ["How does Zeus ultimately resolve the conflict? What does Demeter do in response?", "Through Rhea he offers a compromise: Persephone spends a third of the year below and the rest above, and Demeter gets the honors she wants. Demeter lets the crops grow again and teaches the kings of Eleusis her rites (the Mysteries)."],
    ["What is an allegory? How can the Homeric Hymn to Demeter be understood as an allegory?", "A story whose characters and events stand for something else. Ancient reading: Persephone = the grain buried in the earth (Hades) that returns as the new crop; also read as a girl's marriage (and as a 'dying god' of vegetation). Powell notes the crop allegory doesn't fit Greek farming exactly."],
    ["How is Persephone’s experience like that of Greek girls (parthenoi)?", "Like Greek girls married at ~14 to older men they barely knew, chosen by the father (Zeus gives her to Hades): abrupt loss of childhood and virginity ('plucked' like the narcissus), separation from her mother; the pomegranate marks the bond with her husband."],
    ["Who are Isis and Osiris? Identify three points of similarity between their story and that of Demeter and her daughter.", "Egyptian goddess and her brother-husband, a god killed and dismembered by Seth. Similar: a grieving goddess searches for a lost loved one; she sits by a well in disguise and nurses a royal child, putting him in the fire, until the mother screams; the lost one returns from death (renewal of fertility); both have mystery cults; Greeks identified Isis with Demeter."],
    ["Who is Adonis? What is his relationship to Aphrodite?", "A beautiful youth, Aphrodite's young lover, who dies (killed by a boar) and is mourned — a dying god (≈ Dumuzi).", "e2c2"],
    ["Who is Dumuzi? What is his relationship to Inanna?", "Shepherd-god, Inanna's lover/husband; when she returns from the underworld she hands him over to the demons as her substitute; he returns one day each year.", "e2c2"],
    ["Who is Attis? What is his relationship to Cybele?", "Phrygian youth loved by Cybele, the Great Mother (her priest/companion); maddened at his wedding, he castrates himself and dies; she buries him and his body never decays.", "e2c2"],
    ["Identify two points of similarity among the stories of Persephone, Osiris, Adonis and Dumuzi.", "All are 'dying gods' of fertility who die/go to the underworld and return (cyclically), linked to vegetation; each is tied to a powerful mourning goddess (Demeter, Isis, Aphrodite, Inanna).", "e2c2"],
    ["How is Demeter in Greek literature different from Demeter in Greek religion?", "In literature she has few stories and is subordinated to Zeus; in religion she was a major, popular goddess (the Mysteries were the most honored Greek cult)."],
    ["What form does Demeter take when she visits Eleusis? How is she received by the daughters of Celeus? By Metaneira, his wife?", "An old woman (calls herself Doso, escaped from pirates). The daughters meet her at the Maiden's Well, treat her kindly and bring her home; Metaneira offers her a seat and wine and hires her as nurse (Iambe makes her laugh; she drinks the kykeon)."],
    ["What task is assigned to her? How does she attempt to fulfill this task?", "Nursing the baby prince Demophoön. She anoints him with ambrosia and secretly puts him in the fire each night to make him immortal."],
    ["What goes wrong? What is her response?", "Metaneira spies and screams. Demeter, enraged, throws the child down: he will not be immortal and Eleusis will suffer wars; she reveals herself and demands a temple and altar."],
    ["What famous religious cult is founded at the end of the Homeric Hymn to Demeter? Describe briefly what initiates experienced.", "The Eleusinian Mysteries. After fasting and a procession from Athens on the Sacred Way with torches, initiates drank the kykeon and entered the Telesterion: things done, things shown (the hiera), things said; a flash of light as the hierophant appeared; then celebration. All secret."],
    ["What is the purpose of these rites?", "To win a blessed, happy existence after death (and in origin to make the grain grow); also community among Greeks."]
  ]);

  C("w6r", [
    ["Find Thebes on a map.", "Thebes is in Boeotia, north-west of Athens (beyond Mt. Cithaeron).", "e2c7"],
    ["In what areas does Dionysus exercise power? What visual signs distinguish him in art?", "Wine, the life force/fertility (the wet, active element), ecstasy and madness, theater. Signs: ivy crown, wine cup, thyrsus, leopard (fawn) skin, long robe; bearded (later youthful); panthers pull his chariot."],
    ["What were his female followers called (give three names, and their meanings)?", "Bacchae (“women possessed by Bacchus”), maenads (“raging women”), thyiades (“frenzied ones”). (Bacchantes = followers of either sex.)"],
    ["Who were his male followers and what visuals signs distinguish them in art?", "Satyrs: half-human, with horse tails and ears, erect phalli, pug noses (later goat legs); Silenus = an old, fat, drunken satyr on an ass."],
    ["What animals are associated with Dionysus? What plants are associated with him?", "Animals: bull, goat, lion, leopard/panther (also snakes). Plants: grapevine, ivy, fig, pine (pine cone on the thyrsus)."],
    ["Draw a family tree illustrating the relationships among the following: Zeus & Hera; Cadmus & Harmonia; Semele, Autonoe; Agave & Echion; Pentheus; Athamas & Ino; Dionysus & Ariadne.", "Cadmus + Harmonia → Semele, Autonoë, Agave, Ino. Zeus (husband of Hera) + Semele → Dionysus (+ Ariadne). Agave + Echion → Pentheus. Ino + Athamas (Orchomenus). Autonoë → Actaeon. So Pentheus and Dionysus are cousins; Hera is Dionysus' stepmother."],
    ["Who was King Midas? Briefly recount his story.", "King of Phrygia (son of Gordias and Cybele) who hosted Dionysus well; granted a wish, he asked that all he touched turn to gold — even his food. Dionysus had him wash it off in the river Pactolus (gold in its sands, rich Lydia)."],
    ["Give five examples of stories of resistance to Dionysus.", "Lycurgus of Thrace; the Minyads of Orchomenus; Pentheus (and Agave, Ino, Autonoë) at Thebes; the Proetids of Argos; the Tyrrhenian pirates. (Acrisius of Argos also resisted.)"],
    ["Give two examples of stories in which Dionysus changes his form or appearance.", "With the pirates he becomes a lion (and makes a bear); with the Minyads he appears as a girl, then a lion, bull and panther; in the Bacchae he takes human form as a Lydian stranger (Pentheus sees him as a bull); as a baby Zeus turns him into a goat."],
    ["Who wrote Bacchae and when did the author live?", "Euripides, Athenian tragedian (c. 480–406 BCE); the Bacchae was written c. 406 and produced after his death (c. 405)."],
    ["Where is the play set? Who make up the chorus?", "Thebes, before the royal palace. The chorus = Asian bacchants (loyal followers of Dionysus from Lydia)."],
    ["Why does Dionysus come the Thebes before other Greek cities?", "Thebes is his birthplace, and his mother's sisters slandered Semele (said her lover was mortal); he comes to vindicate her and prove he is a god — Thebes is the first Greek city to receive his rites."],
    ["Who opposes Dionysus? Why? What does this person do to the Theban women who worship Dionysus?", "King Pentheus, who sees the cult as an excuse for drunkenness and sex and a threat to order. He has the women he catches chained in prison and plans to hunt down the rest."],
    ["What is an agon? Briefly, what happens in the agon in Bacchae?", "A formal contest/debate between characters. Pentheus interrogates the captured 'stranger' (the god): mocks his looks, cuts his hair, takes his thyrsus, and jails him."],
    ["How does the agon scene show dramatic irony (= a discrepancy between what the audience knows and what the characters onstage know)?", "The audience knows the stranger is Dionysus himself; Pentheus doesn't — e.g., 'the god is right here … your folly makes you blind' — so Pentheus' threats against the god are ironic."],
    ["What happens in the palace after Dionysus is imprisoned? What happens on Mt. Cithaeron?", "An earthquake/fire destroys the palace and Dionysus walks free. On Cithaeron the maenads nurse wild animals, strike water, wine and milk from the ground, then tear apart cattle and rout the villagers."],
    ["What happens to Pentheus in his second encounter with Dionysus?", "Dionysus puts him in a trance, dresses him as a woman to spy on the maenads and leads him to Cithaeron; he is set on a pine tree, spotted, and torn to pieces by his mother Agave and her sisters."],
    ["How is the conflict in the play resolved? What other Theban story ends with a similar fate for a young man?", "Agave returns with Pentheus' head thinking it a lion's; Cadmus brings her to her senses; Dionysus exiles Cadmus and his daughters (Cadmus & Harmonia later to Elysium). Similar: Actaeon, torn apart by his own hounds."],
    ["Why was Dionysus seen by Greeks as foreign, even though he was worshipped in Greece from at least the 13th century BCE?", "“Foreign” meant different, transgressive: unlike the Olympians he possesses his worshippers with irrational madness; double identity (Thebes and the East), male and female traits — the antithesis of rational order."],
    ["Identify two ways that Dionysus is similar to Demeter.", "Both fertility gods (vine/grain), both with a special link to humans through mystery cults/initiation, joint festivals (the Haloa), both have wrath stories (and both are tied to the underworld)."],
    ["How was Dionysus different from the original Olympian gods to his worshippers? How was he different from these gods to early Christians?", "Worshippers felt him directly — he possessed them (enthusiasm, ecstasy), unlike the distant Olympians. Early Christians saw him as an evil demon (goatish devil), yet his union of god and worshipper (eating flesh, drinking blood; death and rebirth) paralleled Christ."],
    ["What important public events were held in Dionysus’ honor at Athens?", "Dramatic festivals, especially the City Dionysia: tragedies (three tragedians, three tragedies + a satyr play each) and comedies in the Theater of Dionysus."]
  ]);

  C("w7t", [
    ["According to ancient Greeks, what caused death?", "A hostile force: nature (storm, animal), a human enemy, or invisible gods/ghosts (disease) — death did not seem 'natural'."],
    ["What other names was Hades called in Greek or Latin? Why was he called by these names?", "Pluto (“enricher” — wealth comes from under the earth), Dis/Dives (“rich”), Polydegmon (“receiver of many”), Polyxenos (“host to many”); Hades = “the unseen one”. People avoided his real name as dangerous."],
    ["What did Greeks believe normally happened to individual human beings after death?", "The soul (psyche = breath) survives as a shadowy image (eidolon) in Hades' realm — a grim, joyless existence."],
    ["What sort of existence do disembodied souls lead?", "Strengthless, witless shades flitting like dreams, without memory or joy unless they drink blood."],
    ["Give an example of a positive interaction souls can have with the living.", "The ghost of Patroclus appears to Achilles in a dream asking for burial; the dead of the Gold and Silver races become helpful spirits; a friendly snake-spirit at the tomb."],
    ["Give an example of a negative interaction souls can have with the living.", "Unburied or wronged dead haunt and harm the living (vengeful ghosts; Erinyes); ghosts envy the living."],
    ["How did ancient Greeks try to ward off the dead? (Give three examples.)", "Bury their valuables with them; mourning (dark clothes, wailing, tearing hair); tombs/houses for the dead and gravestones; noise to frighten ghosts; pinning the feet (Oedipus); festivals like the Anthesteria that invite and then expel them."],
    ["What is the Odyssey? Who wrote it?", "Homer's Greek epic (c. 800 BCE, ~12,000 lines) of Odysseus' ten-year voyage home from Troy to Ithaca."],
    ["Why does Odysseus go to the underworld? Who does he need to talk to? How does he summon the ghosts?", "Circe tells him to consult the dead seer Tiresias about getting home. He digs a pit, pours honey-milk, wine, and water with barley, and slits the throats of sheep so their blood flows in; the ghosts come to drink."],
    ["What is the nature of Odysseus’ encounters with Elpenor, Anticlea, Agamemnon, and Achilles?", "Elpenor: unburied crewman (fell drunk from Circe's roof) begs for burial. Anticlea: his mother, dead of grief; he tries three times to hug her. Agamemnon: murdered by Clytemnestra — trust no woman. Achilles: better to be a poor man's hired hand than king of the dead."],
    ["What were the crimes of Tantalus, Sisyphus, Ixion and the Danaids? What were their punishments?", "Tantalus served his son Pelops to the gods → eternal hunger and thirst (water and fruit recede). Sisyphus cheated Death → rolls a boulder uphill forever. Ixion lusted after Hera → bound to a fiery wheel. Danaids killed their husbands → carry water in leaky jars."],
    ["What is Elysium? Give at least one example of a hero who ends up here.", "The blessed realm (Elysian Fields/Isles of the Blessed) — in Homer at the ends of the earth, in Vergil part of the underworld for the virtuous. Menelaus (as Helen's husband); also Cadmus & Harmonia."],
    ["What are the Georgics? Who wrote them?", "Vergil's poems about farming; Book 4 tells Orpheus and Eurydice."],
    ["Who is Orpheus? Why did he go to the Underworld? What was the result?", "Thracian singer, son of a Muse and Oeagrus. He went to bring back Eurydice (dead of a snakebite on her wedding day); his song won her release on condition he not look back — he looked and lost her."],
    ["How did Orpheus die? With which god was hostile to him? Which god was he associated with?", "Torn apart by Thracian maenads; Dionysus was hostile (rival cults). He was associated with Apollo (sometimes called his son; killed while honoring Apollo)."],
    ["Does the Orphic cosmogony agree with Hesiod’s? Does it agree with other sources we have read about Dionysus?", "Partly: after Time, the cosmic egg and Phanes it follows Hesiod (Uranus, Cronus, Zeus). It does not match the Dionysus story elsewhere: Orphic Dionysus Zagreus is the son of Zeus and Persephone, torn apart by the Titans."],
    ["What did the Orphics believe normally happened to individual human beings after death?", "Reincarnation (metempsychosis): souls return in new bodies after drinking from Lethe; a pure life can free the soul from the cycle for a blessed afterlife."],
    ["What did Plato add to Orphic beliefs about the underworld in his “Myth of Er”?", "A moral system with judgment and purification (like Purgatory): souls rewarded or punished tenfold for 1000 years, then they themselves choose their next lives before drinking from Lethe."],
    ["What is the Aeneid? Who wrote it? Who is Aeneas?", "Vergil's Latin epic (Vergil 70–19 BCE). Aeneas = Trojan hero, son of Aphrodite and Anchises, who escapes Troy and travels to Italy to found the Roman race."],
    ["Name two figures who help Aeneas in his journey to the underworld. What do they do?", "The Sibyl of Cumae guides him (and drugs Cerberus); the golden bough is his pass (shown to Charon); Charon ferries him; his father Anchises shows him the future of Rome."],
    ["Identify two similarities between what Aeneas encounters in the underworld and what Odysseus encounters. Identify two differences.", "Similar: an unburied companion (Palinurus ≈ Elpenor), a hostile silent soul (Dido ≈ Ajax), a parent he tries three times to embrace (Anchises ≈ Anticlea). Different: Aeneas actually descends and crosses Charon's river (Odysseus calls the dead at a pit); Vergil adds moral punishment/reward for ordinary people, Elysium inside the underworld and a vision of Rome's future (purpose: found Rome, not get home)."]
  ]);

  C("w7r", [
    ["What did the term “hero” mean to Greeks of the classical period? Give three examples of heroes.", "Probably “protector”: a noble figure of the distant past, now dead, worshipped at his tomb. E.g., Theseus, Oedipus, Achilles (also Perseus, Heracles)."],
    ["What was done to honor heroes after their deaths, starting around 800 BCE?", "Hero cult at their tombs (tumulus, heroön): sacrifices, offerings, prayers and requests for help."],
    ["Who was Gilgamesh? What is the Epic of Gilgamesh?", "A real king of Uruk (c. 2600 BCE), two-thirds divine in legend. The Epic is the Mesopotamian poem of his deeds, assembled on twelve tablets by the scribe Sin-leqe-unnini (Nineveh) — the oldest heroic legend."],
    ["Identify two points of similarity between the opening the Epic of Gilgamesh and that of the Odyssey.", "Both begin with “a man” who traveled far, saw much and gained knowledge, and suffered on his journey."],
    ["Who is Enkidu and why was he created? How is he introduced to civilization?", "A wild man made from clay by Aruru to rival and temper the tyrant Gilgamesh. A trapper brings the prostitute Shamhat; after sex with her the animals reject him; he learns to eat bread, drink, wear clothes."],
    ["How does Enkidu meet Gilgamesh? What is their relationship after this meeting? What is Enkidu’s role in their adventures?", "He comes to Uruk and blocks Gilgamesh; they wrestle; they become best friends; Enkidu is the subordinate partner/helper."],
    ["Who is Humbaba and why does Gilgamesh fight him?", "The monstrous guardian of the Cedar Forest; Gilgamesh wants fame (and cedar), and a name that lives on."],
    ["Who is Ishtar and why does Gilgamesh refuse her? How does she respond?", "The goddess of love and war (Inanna). He refuses because her lovers all come to ruin (Tammuz, the bird, the lion, the stallion…). Furious, she has Anu send the Bull of Heaven against Uruk."],
    ["How are the stories of Humbaba and the Bull of Heaven similar? Name one way in which they differ.", "Similar: both are divine monsters killed by the two friends together, angering the gods (broken taboo). Differ: they go seeking Humbaba far away; the Bull is sent against them in Uruk by an angry goddess."],
    ["What awaits humans after death, according to the Epic of Gilgamesh? How does this compare to the underworld depicted in Odyssey, Book 11?", "A dark “house of no return” where the dead eat dust and clay, dressed like birds — the same for good and bad. Like Homer's grim, joyless Hades."],
    ["Who is Utnapishtim and what is his story?", "The flood survivor (≈ Noah, Deucalion) who with his wife was given eternal life by the gods; he tells Gilgamesh the flood story and tests him."],
    ["Who is Siduri, and what does she advise Gilgamesh?", "The divine beer-maid at the edge of the sea: give up the search, accept mortality — eat, drink, wear fine clothes, love your family."],
    ["What is the common theme of the stories of the loaves of bread and the “prickly herb”?", "Humans cannot escape death: Gilgamesh can't even stay awake (seven loaves mark seven days of sleep), and a snake steals the plant of youth."],
    ["Identify, in the Epic of Gilgamesh, one example each of: a wrath story, an etiological story, a dying god story, and a descent to the underworld (katabasis) story.", "Wrath: Ishtar's Bull of Heaven (or Enlil over Humbaba). Etiology: why snakes shed their skin/renew youth. Dying god: Tammuz/Dumuzi, Ishtar's lover. Katabasis: Gilgamesh crosses the waters of death to Utnapishtim (Enkidu's dream of the house of dust)."],
    ["Who are Achilles and Patroklos? What does their story have in common with that of Gilgamesh and Enkidu?", "Iliad hero and his companion; Patroclus dies and Achilles mourns him. Both are the hero's-companion motif: the hero is partly responsible for his friend's death and grieves terribly."],
    ["Name one other Greek myth that we have studied that closely matches a Mesopotamian myth. Give one theory to explain these parallels.", "The flood (Utnapishtim ↔ Deucalion) or the succession myth (Enuma Elish ↔ Hesiod), Inanna/Dumuzi ↔ Aphrodite/Adonis. Theory: stories passed from East to West via bilingual singers/seafarers (borrowing)."],
    ["In the “hero myth”, what is distinctive about the hero’s parents? His childhood?", "One parent may be divine; the birth is miraculous or unusual; little is known of his childhood (often raised in the wild or away from home)."],
    ["How does the hero compare physically, morally or intellectually, with ordinary humans? How well does he fit into human society?", "Far stronger (sometimes cleverer), but a menace to his own people; he fits badly into society (Gilgamesh abusing Uruk)."],
    ["What kinds of activities does the hero engage in?", "Impossible labors, killing monsters, quests to the edge of the world or the underworld, resisting a dangerous woman."],
    ["Identify two ways the hero can relate to the gods differently than ordinary humans.", "He has divine parents/protectors who help him (and divine opponents); he may break taboos against the gods and pay; after death he receives cult or even becomes a god."]
  ]);

  C("w8t", [
    ["Find Argos, Mycenae, the Cyclades, the Caucasus mountains, Egypt and Ethiopia on a map. Which of these did Perseus found?", "Argos and Mycenae on the Argive plain (NE Peloponnese); the Cyclades in the central Aegean; the Caucasus between the Black and Caspian Seas; Egypt and Ethiopia in Africa. Perseus founded Mycenae."],
    ["What is the principal account of the myth of Io? Who wrote it?", "Prometheus Bound, a tragedy by Aeschylus."],
    ["Who is Io? What was her connection with Hera? With Zeus? Did she welcome this connection with Zeus?", "Daughter of the river Inachus; priestess of Hera; Zeus seduced her (turned her into a cow). No — she resisted dreams urging her to Zeus and was driven out by her father on an oracle's command."],
    ["How are Argus, Hermes and Prometheus involved in Io’s story?", "Argus = Hera's hundred-eyed guard; Hermes lulls and kills him, freeing Io; stung by Hera's gadfly she wanders to the Caucasus, where the chained Prometheus foretells her future."],
    ["Where does Io’s story end? How are the Danaids connected to her?", "In Egypt: Zeus restores her with a touch and she bears Epaphus. The Danaids are her descendants (Epaphus → Libya → Belus → Danaus) who return to Argos."],
    ["How does the “all but one” folktale motif apply to the story of the Danaids? Where and how are they punished for their crime?", "49 of the 50 daughters kill their husbands on the wedding night; only Hypermnestra spares Lynceus. In the underworld they must fill a vessel by carrying water in leaky jars."],
    ["How might this story be etiological, about Lerna?", "The husbands' heads were buried in the swamp of Lerna (“which has fifty heads”) — explaining its many springs; also Amymone and Poseidon's trident make the springs of Lerna."],
    ["Who is the grandfather of Perseus? What was he like?", "Acrisius, king of Argos: feared the oracle that his grandson would kill him, imprisoned his daughter, cast her and the baby into the sea, refused to believe Zeus was the father (and resisted Dionysus)."],
    ["Who was the mother of Perseus? How did she conceive him? What happens when his grandfather discovers him?", "Danaë; Zeus came into her bronze chamber as a shower of gold. Acrisius shut mother and child in a wooden box and threw it into the sea."],
    ["Who are Dictys and Polydectes? What is their role in the life of Perseus?", "Brothers on Seriphos: Dictys, a kind fisherman, rescues and raises them; King Polydectes wants Danaë and tricks Perseus into promising a Gorgon's head. Perseus turns Polydectes to stone and makes Dictys king."],
    ["Who are the Gorgons? Why does Perseus have to slay one of them?", "Three monstrous sisters (Stheno, Euryale, Medusa — only Medusa mortal) whose look turns people to stone. He boasted he would bring Medusa's head as his gift to Polydectes."],
    ["How does Perseus prepare for his encounter with the gorgon? Who helps him?", "Athena instructs him; he forces the Graeae (by stealing their one eye) to tell him where the nymphs are; the nymphs give the cap of Hades, winged sandals and a pouch; Hermes gives a sickle-sword and polished shield."],
    ["How do his magic implements help him in his battle with Medusa and afterwards?", "He flies with the sandals, watches her in the shield-mirror, cuts off her head with the sword, hides it in the pouch, and escapes the other Gorgons invisible in the cap; later he uses the head to petrify enemies."],
    ["How does he defeat Polydectes?", "He walks into the king's banquet and shows the Gorgon's head — Polydectes and his friends turn to stone."],
    ["What is the principal account of the story of Perseus and Andromeda? Who wrote it?", "Ovid's Metamorphoses (Book 4)."],
    ["Who is Andromeda? Why is she in danger? How does Perseus help her?", "Daughter of King Cepheus and Cassiopea (Ethiopia/Joppa). Her mother boasted she was more beautiful than the Nereids; Poseidon sent a flood and the sea monster Ceto; an oracle (Ammon) demanded her sacrifice. Perseus kills the monster with his sword and marries her."],
    ["What was created by the severed head of the monster?", "The Gorgon's head created coral (seaweed turned to stone) — and its dripping blood created snakes in the Libyan desert. (From Medusa's neck sprang Pegasus and Chrysaor.)"],
    ["How does Acrisius die?", "At games in Thessaly, Perseus' discus is blown off course and strikes him — the oracle fulfilled."],
    ["What happens to Perseus, Andromeda, Cepheus, Cassiopea and Ceto, after their deaths?", "Athena places them among the stars as constellations."],
    ["What is a “girl’s tragedy” story? Give an example from this chapter.", "A folktale pattern: prohibition, seclusion, violation (usually by a god), birth of a son, threat of punishment, liberation (and recognition). Danaë (also Io)."],
    ["What does Perseus’ story have in common with those of other Greek legendary heroes, like Achilles or Hercules?", "A divine father (Zeus), unusual conception, exile/growing up away from home, impossible labors with divine help, killing monsters."],
    ["Identify three folktale motifs in the story of Perseus.", "Magic items (cap, sandals, pouch); three sisters (Gorgons/Graeae); wicked king; outcast hero; slays a monster; wins a princess and a kingdom; happy ending."],
    ["What was “Gorgo” before the myth of Perseus? What was her function?", "A free-standing staring-eyed demon (in Homer, on Agamemnon's shield) — an apotropaic image to ward off evil/the evil eye."]
  ]);

  C("w8r", [
    ["Find Phoenicia, Crete, Thebes, Mt. Cithaeron, Athens, Corinth, Delphi and Argos on a map.", "Phoenicia: Levant coast (Tyre, Sidon). Crete: big island south of the Aegean. Thebes: Boeotia; Mt. Cithaeron just south of it, toward Attica; Athens in Attica; Corinth on the Isthmus; Delphi on Mt. Parnassus; Argos on the Argive plain."],
    ["What is unique about the city of Thebes in Greek legend?", "It has two separate foundation stories (Cadmus; Amphion & Zethus)."],
    ["Why was Cadmus traveling around the Mediterranean?", "His father Agenor sent him (and his brothers) to find his sister Europa, carried off by Zeus as a bull, forbidding them to return without her."],
    ["Where does he go for information about his quest? What is he told to do?", "Delphi: give up the search, follow a cow, and found a city where she lies down."],
    ["Describe, briefly, the creature he slays. How does this creature kill his companions (identify three different ways)? How does Cadmus finally defeat it?", "A huge serpent sacred to Ares guarding the spring (golden crest, fiery eyes, triple tongue). It kills his men by biting, crushing in its coils, and poisonous breath. Cadmus (lion skin, javelin) drives it back and pins its neck to an oak with his javelin."],
    ["Explain how this exploit makes Cadmus a typical Indo-European hero. Name two other heroes who perform a similar exploit.", "Dragon-slaying = victory over death/chaos (a creation myth 'downgraded' to a city founding). Also Marduk (Tiamat), Zeus (Typhoeus), Apollo (Python), Perseus, Heracles."],
    ["Who advises him after the fight and what happens as a result of her advice?", "Athena: sow the dragon's teeth. Armed men (Spartoi) spring up and kill each other until five remain — the founding families of Thebes."],
    ["Who is Harmonia and what does Cadmus have to do in order to marry her? What are Harmonia’s two wedding gifts?", "Daughter of Ares and Aphrodite. He must serve Ares eight years in penance for the serpent. Gifts: a necklace made by Hephaestus and a robe (both cursed)."],
    ["Identify Ino, Semele, Agave, and Actaeon and briefly describe their fates.", "Daughters (and grandson) of Cadmus: Ino, maddened by Hera, kills her son and leaps into the sea (Leucothea); Semele is burned up by Zeus' glory; Agave tears apart her son Pentheus; Actaeon (son of Autonoë) becomes a stag and is killed by his own hounds."],
    ["How are Amphion and Zethus related to Cadmus? What do they do for Thebes? How did ancient authors reconcile this story with the story of Cadmus?", "Twin sons of Zeus and Antiope, daughter of Nycteus (linked by later genealogy to Cadmus' family). They build Thebes' walls — Amphion with his lyre, Zethus by strength. Reconciled: Cadmus founded the upper city (Cadmeia), the twins walled the lower city (Thebes)."],
    ["Who is Antiope? Briefly recount her story. Identify two story patterns that can be found in the myth of Antiope, Dirce, Amphion and Zethus.", "Theban princess seduced by Zeus; her father drives her out; she marries the king of Sicyon; her uncle Lycus kills him and drags her back; she bears twins on Cithaeron, raised by a shepherd; Dirce tortures her; she escapes to her sons, who tie Dirce to a bull. Patterns: girl's tragedy; wicked stepmother/aunt; magic twins (folktale); double founding."],
    ["Draw a family tree of Jocasta, Creon, Laius, Oedipus, Antigone, Eteocles and Polynices. Briefly identify each of these figures.", "Menoeceus → Jocasta and Creon (siblings). Laius + Jocasta → Oedipus. Oedipus + Jocasta → Eteocles, Polynices, Antigone (and Ismene). Laius: king, killed by his son; Jocasta: queen, mother/wife of Oedipus; Creon: her brother, later king; Oedipus: solved the riddle; Eteocles & Polynices: sons who kill each other; Antigone: buries Polynices."],
    ["What prohibition does Laius violate? How does he try to escape the consequences? What goes wrong?", "Apollo's oracle: have no son (or the son will kill him) — he begets one while drunk. He has the baby exposed on Mt. Cithaeron with pinned feet. The shepherd pities it and it is raised in Corinth; grown, Oedipus kills him at a crossroads."],
    ["What is the most famous version of the story of Oedipus? Who wrote it?", "Oedipus the King (Oedipus Rex), by Sophocles."],
    ["What does Oedipus do to become king of Thebes? What goes wrong under his reign?", "He solves the Sphinx's riddle (answer: a human) and so wins the queen and the throne. A plague strikes Thebes because Laius' murderer (miasma) is unpunished."],
    ["Where does he go for information about the crisis? What does he tell the Theban citizens?", "To Delphi (via Creon). He proclaims that anyone who knows the killer must speak, and curses the killer — even if in his own house — with exile."],
    ["What does he learn, in the course of the play, about his own identity? What does he do when he learns this information? What does Jocasta do?", "That he is the son of Laius and Jocasta — he killed his father and married his mother. He blinds himself with Jocasta's brooch pins and goes into exile. Jocasta hangs herself."],
    ["Identify three ways that Oedipus is a “study in the contrast between being and appearance” (Powell, p. 490)?", "He thinks he is Corinthian but is Theban; he solves riddles but not the riddle of himself; he judges right and wrong but is the worst criminal; the sighted man is blind (Tiresias, blind, sees); Thebes' savior is its destroyer."],
    ["How is Oedipus a typical legendary hero, like Gilgamesh, Achilles or Heracles? How is he different? (Give two points for each question.)", "Typical: unusual birth/exposure, journey, defeats a monster (the Sphinx), wins a queen and kingdom, mysterious death and cult. Different: no divine parent, an unheroic name (“swollen foot”), raised in a city (Corinth) not the wild, wins by intelligence not strength."],
    ["Who succeed Oedipus as kings of Thebes? What goes wrong?", "His sons Eteocles and Polynices, to rule in alternate years; Eteocles refuses to give up the throne, so Polynices leads the Seven against Thebes — civil war."],
    ["What does Oedipus say about his sons, according to Sophocles in Oedipus at Colonus? What does he say about his daughters?", "He curses his sons (they will die by each other's hands) and calls them not his sons; he praises his daughters, who cared for him — “they are true men, not women”."],
    ["Draw a family tree of Adrastus, his two daughters, Polynices, Tydeus, Eriphyle and Amphiaraus. Why did Eriphyle later become proverbial for treachery?", "Adrastus (king of Argos) → two daughters married to Polynices and Tydeus; Adrastus' sister Eriphyle married the seer Amphiaraus. Bribed by Polynices with Harmonia's necklace, she sent her husband to a war she knew would kill him."],
    ["How many heroes attacked Thebes? How many defended it?", "Seven attackers, seven defenders — one at each of the seven gates."],
    ["Describe, briefly, the deaths of Tydeus, Eteocles, and Polynices. Who became the next king of Thebes? What order did he give, concerning Polynices’ corpse?", "Tydeus, mortally wounded, gnaws the brains of his enemy Melanippus, so Athena withholds immortality. Eteocles and Polynices kill each other in a duel. Creon becomes king and forbids burial of Polynices (and the attackers)."],
    ["Who challenged this order, and why did she do this? Name the principles at stake in this conflict.", "Antigone buries her brother: duty to family and the gods' unwritten laws. Principles: family vs. state (divine/natural law vs. human decree), individual vs. powerful ruler, women vs. men."],
    ["What is the most famous version of her story, and who wrote it?", "Antigone, by Sophocles (441 BCE)."]
  ]);

  C("w9t", [
    ["Find Troezen, Athens and Thebes on a map.", "Troezen: NE Peloponnese across the Saronic Gulf from Athens. Athens: Attica. Thebes: Boeotia, north-west of Athens."],
    ["With which Greek city was Theseus associated? What important development in the legends surrounding him took place during the sixth and fifth centuries? Why did this happen at this time and place?", "Athens. He was turned from a minor figure into Athens' national hero — a 'new Heracles' with new labors, an epic (Theseïs), a festival and cult. Because Athens' leaders (Pisistratus, then Miltiades, Cimon) used him as political propaganda for Athenian unity and power."],
    ["What three claims did the Athenians make about their own mythical origins?", "Descended from Cecrops; autochthonous (born from the soil of Athens); descended from Athena."],
    ["Who was Erichthonius? How was he conceived and born?", "An early king of Athens. Hephaestus pursued Athena and ejaculated on her leg; she wiped it off with wool onto the ground, and Earth bore the child (name ≈ “wool” + “earth”)."],
    ["Who were the three women charged with protecting his basket and what happened to them? Where have we seen this story type before?", "Cecrops' daughters Aglaurus, Herse and Pandrosus; told not to look inside; Aglaurus and Herse looked, saw a snake/snake-child, went mad and leapt from the Acropolis; Pandrosus obeyed. Same type as Pandora's jar (a forbidden container opened out of curiosity)."],
    ["Who were the arrephoroi and what did they do for Athena? What is their connection to the women in question (7)?", "Two young girls who lived a year on the Acropolis, wove Athena's robe, and at the Arrhephoria carried secret baskets down and up at night. The myth of Cecrops' daughters and the basket explains (is etiological for) this ritual."],
    ["Draw a genealogical chart connecting Herse, Hermes, Cephalus, Erechtheus, Procris, Eos/Aurora, and Phaethon.", "Herse + Hermes → Cephalus. Erechtheus → Procris. Cephalus marries Procris; Eos (Aurora, Dawn) also loves Cephalus → Phaethon (by some accounts)."],
    ["Why does the Cretan king Minos need Procris’ help, and what does he give her as a reward? What eventually happens to his gift?", "Pasiphaë cursed him so his lovers died (he needed a cure — Procris cured him with a Circean herb). He gives her the hound Laelaps (catches anything) and an unerring javelin; the javelin later kills Procris herself (Cephalus throws it by accident)."],
    ["What is the problem in the marriage of Procris and Cephalus? How does each spouse contribute to this problem? How is the problem resolved?", "Jealousy and distrust: Cephalus tests her faithfulness in disguise (she yields/flees); she suspects him of loving 'Aura' and spies on him while he hunts. Resolved tragically: he kills her by accident with the javelin (they had been reconciled before)."],
    ["Who tells the story of Procris and Cephalus and what moral does it illustrate? Do you think he is serious? Who were his original audience?", "Ovid (Cephalus narrates it in the Metamorphoses): a moral about jealousy/trust in marriage. Probably not entirely serious — ironic. Audience: sophisticated upper-class Romans of Augustus' time."],
    ["Draw a genealogical chart connecting Pandion, Procne, Philomela, Erechtheus, Tereus, Ares/Mars and Itys.", "Pandion → Procne, Philomela, Erechtheus. Ares/Mars → Tereus. Tereus + Procne → Itys."],
    ["What is Tereus’ main vice? How do the events Ovid describes illustrate this vice?", "Lust. On sight of Philomela he burns with desire, deceives Pandion with false tears, rapes her in a hut in the woods, cuts out her tongue, keeps returning to her, and lies to Procne that she is dead."],
    ["How does Tereus get caught, and what does Procne do to punish him? What makes her hesitate?", "Philomela weaves the story into a tapestry and sends it to Procne. During Dionysus' rites Procne rescues her, kills her son Itys and serves him to Tereus. She hesitates because the little boy hugs her and calls her mother (he looks like his father, which decides her)."],
    ["Compare Procne to at least two other figures we have seen who mistreat their own children. What is her ultimate fate?", "Like Agave (tears apart Pentheus), Ino (boils Melicertes), the Minyads (eat a child), Tantalus (serves Pelops to the gods), Medea. She becomes a bird — the nightingale (Philomela the swallow, Tereus the hoopoe)."],
    ["Who is Aegeus and why does he visit the Delphic oracle? Who does he consult about answer and what is the result?", "King of Athens, childless, asking how to get an heir. The riddling answer (don't open the wineskin until you reach Athens) he takes to Pittheus of Troezen, who gets him drunk with his daughter Aethra → Theseus is conceived."],
    ["Who are Theseus’ parents? (Name all three!) What test does his mortal father set for him?", "Aegeus and Poseidon (fathers) and Aethra (mother). Lift the rock under which Aegeus hid a sword and sandals, then bring them to Athens."],
    ["What does Theseus do to the figures depicted around the wine cup in Powell fig. 16.7?", "Kills each by his own method: Cercyon (wrestler) — wrestled to death; Procrustes — fitted to his own bed; Sciron — kicked off the cliff to the turtle; the Marathonian bull — captured and sacrificed; Sinis — torn apart by the pines; the Crommyonian sow — killed. (And the Minotaur in the center.)", "e2c8"],
    ["Who is Medea and what is her role in the legends of Theseus?", "A witch (from Colchis), wife of Aegeus; the female enemy: she sends Theseus against the Marathonian bull and tries to poison him; when Aegeus recognizes the sword she flees to Asia."],
    ["Who were the Amazons and what is the significance, for fifth century Greeks, of their battle with Theseus (the Amazonomachy)?", "Warrior women, daughters of Ares, who invert Greek gender norms. Theseus abducted their queen (Antiope/Hippolyta) and defeated their invasion of Athens — after Marathon (490 BCE) it symbolized Athens' victory over the Persians and barbarism (shown on the Parthenon)."],
    ["How does Theseus’ father die? How does Theseus’s son die? What happens to Theseus’ mistresses and his wife? (Please identify them by name.)", "Aegeus leaps into the sea when Theseus forgets to change the black sail. Hippolytus is killed when Poseidon's bull frightens his horses (Theseus' curse). Ariadne is abandoned on Naxos (rescued by Dionysus); Antiope/Hippolyta is cast off (dies); Phaedra hangs herself."],
    ["Why does Aphrodite punish Hippolytus? How does Phaedra feel about the sexual passion Aphrodite sends? How does Hippolytus feel about the proposal the Nurse brings to him?", "He scorns her and worships only Artemis, refusing love. Phaedra is ashamed and tries to resist, even to die rather than act. Hippolytus is disgusted and launches a tirade against women."],
    ["What did Euripides change from the original myth? Identify the folktale type here and give two other examples.", "He made Phaedra sympathetic — she doesn't proposition Hippolytus herself (the Nurse does) and struggles against her passion (a 'sanitized' version). Type: Potiphar's wife — Joseph (Genesis 39), Bellerophon, Peleus."],
    ["Who is Pirithous and what do he and Theseus attempt together? What are the consequences for each? What are the consequences for the women involved?", "King of the Lapiths, son of Ixion, Theseus' sworn friend. They seek daughters of Zeus as wives: Theseus abducts the child Helen, then both go to the underworld for Persephone. Stuck on chairs; Heracles frees Theseus, Pirithous stays forever. Helen is taken back by her brothers, who enslave Aethra."],
    ["How does Theseus’ death resemble his father’s?", "Both fall from a height: Theseus is pushed off a cliff on Scyros by King Lycomedes, as Aegeus threw himself from a cliff into the sea."]
  ]);

  C("w9r", [
    ["Who told the myths that we know about Athens? Who told the myths that we know about Crete? Whose (later) versions of these myths actually survive?", "Athens' myths were told by Athenians; Crete's myths were also told by mainland Greeks, mostly Athenians. The surviving versions are mostly later Roman writers (Ovid, Catullus) and Apollodorus."],
    ["Where did Agenor rule? Which of his sons was the first founder of Thebes?", "Phoenicia (Tyre/Sidon). Cadmus."],
    ["What happens to Agenor’s daughter? Why don’t “grandeur and love go well together,” according to Ovid?", "Europa is carried off by Zeus disguised as a bull. Because the king of the gods must give up his majesty (sceptre, thunderbolt) and act like a cow-chasing bull to win her."],
    ["Where does Agenor’s daughter end up? What gifts does she receive? Name her three children.", "Crete. Talos (bronze giant), Laelaps (unfailing hound), a javelin. Minos, Sarpedon, Rhadamanthys."],
    ["Briefly summarize the wrath story that centers on the Cretan bull, naming all of the participants (god, king, queen, craftsman, offspring).", "Minos asks Poseidon for a bull to prove his kingship and promises to sacrifice it, but keeps it (offense). Poseidon (anger) makes Queen Pasiphaë lust for the bull; the craftsman Daedalus builds a wooden cow; the offspring is the Minotaur, shut in the Labyrinth."],
    ["In what city does this story take place? Where is the offspring kept?", "Cnossus on Crete. In the Labyrinth built by Daedalus."],
    ["In what work does Ovid tell this story? Identify two actions the queen takes, according to Ovid, in order to appeal to the bull. How does she handle rivals?", "The Ars Amatoria (Art of Love), Book 1. She wears color-coordinated outfits, fusses over her hair and mirror, picks him tender grass and follows the herd. She has rival cows yoked to the plow or sacrificed."],
    ["Why does Minos quarrel with Athens? How does he get the upper hand and what penalty does he impose on the Athenians?", "His son Androgeus, champion at the Panathenaic games, was sent by Aegeus against the Marathonian bull and killed. Minos takes Megara, but can't take Athens until Zeus sends plague and famine; tribute: seven boys and seven girls (every nine years) for the Minotaur."],
    ["How does Theseus prove his divine birth to Minos?", "Minos throws a ring into the sea; Theseus dives and comes back with a wreath from Amphitrite, wife of Poseidon (Bacchylides)."],
    ["How does Theseus escape the labyrinth? Who gives him the essential gift and why?", "By a ball of thread tied to the entrance and unrolled behind him (Daedalus' idea). Ariadne gives it because she has fallen in love with him and wants him to marry her and take her away."],
    ["Why does Theseus abandon Minos’ older daughter? What goes wrong when he marries the younger daughter? Identify one trait shared by the wife and daughters of Minos.", "Disgusted by Ariadne's betrayal of her father (she was treacherous), he leaves her on Naxos. Phaedra falls in love with her stepson Hippolytus. Shared trait: uncontrollable, transgressive sexual passion."],
    ["Who rescues Ariadne?", "Dionysus, who marries her (her crown becomes a constellation)."],
    ["Who is Daedalus? Where does he come from and why does he come to Crete?", "The master craftsman/inventor, from Athens (descendant of Cecrops). Exiled for killing his nephew and apprentice Perdix (inventor of the saw), he goes to Crete."],
    ["Who is Icarus? Who tells his story? How does this story show that “adversity sharpens the mind”?", "Daedalus' son (by a slave girl). Ovid. Imprisoned by Minos with land and sea blocked, Daedalus invents wings of feathers and wax to escape through the air."],
    ["Why does the poet call Icarus “overly rash in his adolescent bravado”? What other moral (in addition to the one in question 14) does this story illustrate? Is this author always serious about the morals he offers?", "He ignores his father's instructions, flies too high, the wax melts and he falls. Moral: 'nothing too much' — keep the middle course / obey your father. No — Ovid is often ironic (in the Art of Love the point is that Cupid can't be restrained)."],
    ["What is Daedalus’ last accomplishment? How is he finally revenged on Minos?", "At King Cocalus' court in Sicily he threads a spiral conch shell (thread tied to an ant), which reveals him to Minos. Cocalus' daughters scald Minos to death in his bath."],
    ["Who lived on Crete prior to 1450 BCE? What sport did they play, according to their wall paintings? What link has been suggested between this sport and the story of Theseus and the minotaur?", "The Minoans (non-Greeks). Bull-leaping. The dangerous bull games (and youths facing bulls) may lie behind the legend of the man-eating Minotaur and the Athenian youths."],
    ["What deity did this population worship? What link has been suggested between this deity and Ariadne?", "A mother/snake goddess (bare-breasted woman holding snakes). Ariadne (“very holy one”) may be that goddess, demoted to a folktale princess."],
    ["Why didn’t they still inhabit the island in the classical period?", "Minoan palaces were destroyed c. 1450 BCE (cause unknown; not the earlier Thera eruption); Mycenaean Greeks took over Cnossus, which was destroyed again c. 1400 and 1200 — Greek culture replaced the Minoan."],
    ["Name three of elements of Theseus myths that belong to folklore. Name three elements that belong to heroic legend. Who developed and promoted the heroic version of Theseus?", "Folklore: wandering hero, wicked king, man-eating monster demanding human sacrifice, princess who helps, magic thread/trickster craftsman, black/white sails, three wishes. Legend: a named hero with real parents and city (Athens), divine father, cult/shrine and bones, labors like Heracles. Promoted by the Athenians — Pisistratus, Miltiades, Cimon."]
  ]);

  window.DATA_TERMS.push(...cards);
})();
